12	// plugin's delegation surface for task context (COR-2217). The graph owns the
13	// queryable store; the brief calls this instead of maintaining its own copy of
14	// the snapshot. Field names mirror the provider's contextResponse contract.
15	type graphTaskContext struct {
16		SchemaVersion string                 `json:"schema_version"`
17		Commit        string                 `json:"commit"`
18		Tree          string                 `json:"tree"`
19		Symbols       []graphContextSymbol   `json:"symbols"`
20		Relations     []graphContextRelation `json:"relations"`
21		Tests         []graphContextSymbol   `json:"tests"`
22		LatencyMS     int64                  `json:"latency_ms"`
