50	// graphTaskContextTimeout bounds the delegation subprocess. The command
51	// answers from an indexed store in well under a second; the margin covers a
52	// cold binary start and a loaded machine, not a build.
53	const graphTaskContextTimeout = 15 * time.Second
54	
55	// fetchGraphTaskContext asks the graph plugin for task context. Any error —
56	// binary missing, a plugin version without the `context` verb, malformed
57	// output — reads as "delegation unavailable" and the caller falls back; it is
58	// never surfaced as a brief failure.
59	func fetchGraphTaskContext(ctx context.Context, runner CommandRunner, repoDir, graphBinary, task string, limit, testsLimit int) (graphTaskContext, error) {
60		if runner == nil {
61			return graphTaskContext{}, fmt.Errorf("graph context requires a command runner")
62		}
63		binary := strings.TrimSpace(graphBinary)
64		if binary == "" {
65			binary = "entire"
66		}
67		runCtx, cancel := context.WithTimeout(ctx, graphTaskContextTimeout)
68		defer cancel()
69		args := []string{"graph", "context", "--repo", repoDir, "--task", task, "--limit", fmt.Sprint(limit), "--tests-limit", fmt.Sprint(testsLimit)}
70		ignores, err := semanticProviderIgnoreFiles(repoDir)
71		if err != nil {
72			return graphTaskContext{}, err
73		}
74		for _, ignore := range ignores {
75			args = append(args, "--ignore-file", ignore)
76		}
77		stdout, stderr, err := runner.Run(runCtx, repoDir, binary, args...)
78	
79		if err != nil {
80			detail := strings.TrimSpace(string(stderr))
81			if detail == "" {
82				detail = strings.TrimSpace(string(stdout))
83			}
84			if detail != "" {
85				return graphTaskContext{}, fmt.Errorf("graph context: %w: %s", err, firstLine(detail))
86			}
87			return graphTaskContext{}, fmt.Errorf("graph context: %w", err)
88		}
89		var response graphTaskContext
90		if err := json.Unmarshal(stdout, &response); err != nil {
91			return graphTaskContext{}, fmt.Errorf("graph context returned unparseable output: %w", err)
92		}
93		return response, nil
94	}
