103	// graphContextSymbolRecords projects provider symbols into the brief's
104	// semanticRecord shape so every downstream consumer (departed-file filtering,
105	// caps, likely-file synthesis, rendering) works unchanged.
106	func graphContextSymbolRecords(symbols []graphContextSymbol) []semanticRecord {
107		records := make([]semanticRecord, 0, len(symbols))
108		for _, symbol := range symbols {
109			records = append(records, semanticRecord{
110				RecordType:    "symbol",
111				ID:            symbol.ID,
112				Kind:          symbol.Kind,
113				Name:          symbol.Name,
114				QualifiedName: symbol.QualifiedName,
115				FilePath:      symbol.FilePath,
116				StartLine:     symbol.StartLine,
117				EndLine:       symbol.EndLine,
118				Signature:     symbol.Signature,
119				Language:      symbol.Language,
120			})
121		}
122		return records
123	}
124	
125	// graphContextRelationRecords keeps only relations whose endpoints are both
126	// among the returned context symbols (or external graph endpoints): that is
127	// the brief packet's relation contract, enforced again by the semantic cap and
128	// departed-file filtering, and an edge to a symbol the packet does not show is
129	// an opaque ID the agent cannot use. Test edges are conveyed by the tests
130	// section instead.
131	func graphContextRelationRecords(symbols []graphContextSymbol, relations []graphContextRelation) []semanticRecord {
132		known := make(map[string]struct{}, len(symbols))
133		for _, symbol := range symbols {
134			known[symbol.ID] = struct{}{}
135		}
136		endpointKnown := func(id string) bool {
137			if _, ok := known[id]; ok {
138				return true
139			}
140			return strings.HasPrefix(id, "external:")
141		}
142		records := make([]semanticRecord, 0, len(relations))
143		for _, relation := range relations {
144			if !endpointKnown(relation.FromID) || !endpointKnown(relation.ToID) {
145				continue
146			}
147			records = append(records, semanticRecord{
148				RecordType: "relation",
149				FromID:     relation.FromID,
150				ToID:       relation.ToID,
151				Type:       relation.Type,
152				Confidence: relation.Confidence,
153			})
154		}
155		return records
156	}
