158	func graphContextTestsResult(tests []graphContextSymbol) semanticTestsResult {
159		suggestions := make([]semanticTestSuggestion, 0, len(tests))
160		for _, record := range graphContextSymbolRecords(tests) {
161			suggestions = append(suggestions, semanticTestSuggestion{Symbol: record, Reason: "task match (graph store)"})
162		}
163		return semanticTestsResult{Roots: []semanticRecord{}, Suggestions: suggestions}
164	}
